import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Pie } from 'react-chartjs-2';
import Navbar from '../components/Navbar';
import './AdminDashboard.css';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';

ChartJS.register(ArcElement, Tooltip, Legend);

const AdminDashboard = ({ user, onLogout }) => {
  const [dateFilter, setDateFilter] = useState('today');
  const navigate = useNavigate();

  // Mock attendance data
  const attendanceData = {
    total: 16,
    present: 12,
    absent: 4
  };

  const absentees = [
    'Robert Johnson',
    'Michael Brown',
    'David Miller',
    'Sarah Davis'
  ];

  // Mock salary data
  const salaryData = {
    pending: 135000,
    released: 765000,
    pendingEmployees: 3
  };

  const pendingPayrolls = [
    { name: 'Robert Johnson', amount: '₱46,029' },
    { name: 'Michael Brown', amount: '₱48,730' },
    { name: 'David Miller', amount: '₱45,494' }
  ];

  const attendanceChartData = {
    labels: ['Present', 'Absent'],
    datasets: [
      {
        data: [attendanceData.present, attendanceData.absent],
        backgroundColor: ['#10b981', '#ef4444'],
        borderColor: ['#059669', '#dc2626'],
        borderWidth: 2,
      }
    ]
  };

  const salaryChartData = {
    labels: ['Paid', 'Not Paid', 'Pending'],
    datasets: [
      {
        data: [17, 3, 0],
        backgroundColor: ['#10b981', '#fbbf24', '#6366f1'],
        borderColor: ['#059669', '#f59e0b', '#4f46e5'],
        borderWidth: 2,
      }
    ]
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: true,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          padding: 15,
          font: { size: 12, weight: '600' }
        }
      }
    }
  };

  return (
    <div className="admin-container">
      <Navbar user={user} onLogout={onLogout} />
      
      <div className="container">
        <div className="welcome-section">
          <h1>Welcome, {user?.employeeName || 'Admin'}</h1>
          
          <div className="filter-section">
            <span>Filter by Date:</span>
            <div className="filter-buttons">
              <button 
                className={dateFilter === 'today' ? 'active' : ''} 
                onClick={() => setDateFilter('today')}
              >
                Today
              </button>
              <button 
                className={dateFilter === 'week' ? 'active' : ''} 
                onClick={() => setDateFilter('week')}
              >
                Last Week
              </button>
              <button 
                className={dateFilter === 'month' ? 'active' : ''} 
                onClick={() => setDateFilter('month')}
              >
                Last Month
              </button>
            </div>
            <div className="date-picker">
              <span>📅 {new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
            </div>
          </div>
        </div>

        <div className="dashboard-grid">
          {/* Attendance Tracker */}
          <div className="tracker-card">
            <div className="card-header">
              <h2>📊 Attendance Tracker</h2>
              <p>{new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
              <p className="total-label">Total {attendanceData.total} employees</p>
            </div>
            
            <div className="chart-container">
              <div className="pie-chart">
                <Pie data={attendanceChartData} options={chartOptions} />
              </div>
            </div>

            <div className="tracker-stats">
              <div className="stat">
                <span className="stat-label">Total Present</span>
                <span className="stat-value present">✓ {attendanceData.present}</span>
              </div>
            </div>

            <div className="absentees-list">
              <strong>Absentees:</strong>
              <ul>
                {absentees.map((name, idx) => (
                  <li key={idx}>• {name}</li>
                ))}
              </ul>
            </div>
          </div>

          {/* Salary Tracker */}
          <div className="tracker-card">
            <div className="card-header">
              <h2>💰 Salary Tracker</h2>
              <p>{new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
              <p className="total-label">Total 20 employees</p>
            </div>

            <div className="chart-container">
              <div className="pie-chart">
                <Pie data={salaryChartData} options={chartOptions} />
              </div>
            </div>

            <div className="salary-stats">
              <div className="stat-row">
                <span>Pending Salaries</span>
                <span className="amount">₱{salaryData.pending.toLocaleString()}</span>
              </div>
              <div className="stat-row">
                <span>Released Salaries</span>
                <span className="amount">₱{salaryData.released.toLocaleString()}</span>
              </div>
              <div className="stat-row">
                <span>Pending Employees</span>
                <span className="badge">{salaryData.pendingEmployees}</span>
              </div>
            </div>

            <div className="payroll-section">
              <strong>Pending Payrolls:</strong>
              {pendingPayrolls.map((payroll, idx) => (
                <div key={idx} className="payroll-item">
                  <span>{payroll.name}</span>
                  <span className="amount">{payroll.amount}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
